package com.piano.customers.domain;

import java.util.Objects;
import java.util.regex.Pattern;

/**
 * Public customer id, generated by the tenant. It is used as a URL path segment ({@code
 * /customers/{id}}), so it is restricted to URL-safe characters that need no encoding and have no
 * special meaning in a path ({@code /}, {@code ;}, {@code .} and {@code ..} would make a stored
 * customer unreachable).
 */
public record CustomerId(String value) {

    public static final int MAX_LENGTH = 128;

    private static final Pattern ALLOWED = Pattern.compile("[A-Za-z0-9_-]{1," + MAX_LENGTH + "}");

    public CustomerId {
        Objects.requireNonNull(value, "value");
        if (!ALLOWED.matcher(value).matches()) {
            throw new DomainValidationException(
                    "Customer id must be 1-"
                            + MAX_LENGTH
                            + " characters: letters, digits, underscore or hyphen");
        }
    }
}
